window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-10101\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεχής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1583 na letra δ · nº geral 10101</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">descontínuo; interrompido. 〈διέχω〉</p></section></article>\n<article id=\"entry-dgp-10102\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διέχω</h1><div class=\"entry-meta\"><span>DGP · ordem 1584 na letra δ · nº geral 10102</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διέξω, aor.2 διέσχον) 1 penetrar através, διά e gen . 2 estender-se por 3 afastar; separar; manter separado 4 segurar com força; sujeitar; conter 5 estar separado; distar. 〈διά, ἔχω〉</p></section></article>\n<article id=\"entry-dgp-10103\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διεψευσμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 1585 na letra δ · nº geral 10103</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. erroneamente; falsamente. 〈δια­ψεύδω〉</p></section></article>\n<article id=\"entry-dgp-10104\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίζημαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1586 na letra δ · nº geral 10104</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διζήσομαι, aor. ἐδιζησάμην) 1 procurar alguém 2 procurar obter 3 procurar saber; procurar compreender 4 questionar; interrogar; investigar 5 esforçar por; desejar, inf.</p></section></article>\n<article id=\"entry-dgp-10105\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίζυξ, υγος</h1><div class=\"entry-meta\"><span>DGP · ordem 1587 na letra δ · nº geral 10105</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 atrelado a dois 2 duplo. 〈δίς, ζεύγνυμι〉</p></section></article>\n<article id=\"entry-dgp-10106\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1588 na letra δ · nº geral 10106</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) poét. 1 estar em dúvida; hesitar ♦ méd. 2 procurar. 〈δίς〉</p></section></article>\n<article id=\"entry-dgp-10107\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίζως,</h1><div class=\"entry-meta\"><span>DGP · ordem 1589 na letra δ · nº geral 10107</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. sing. -ων (masc.) de forma dupla, epít. de Pã. 〈δίς, ζωή〉</p></section></article>\n<article id=\"entry-dgp-10108\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διηγέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1590 na letra δ · nº geral 10108</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">expor ponto por ponto; contar detalhadamente; descrever.</p></section></article>\n<article id=\"entry-dgp-10109\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διήγημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1591 na letra δ · nº geral 10109</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">exposição; narração; relato. 〈διη­γέομαι〉</p></section></article>\n<article id=\"entry-dgp-10110\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διήγησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1592 na letra δ · nº geral 10110</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">exposição; narração; explicação. 〈διηγέομαι〉</p></section></article>\n<article id=\"entry-dgp-10111\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διηεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 1593 na letra δ · nº geral 10111</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(3ª sing. διῄει, 3ª pl. διῄεσαν) cf. δίειμαι2.</p></section></article>\n<article id=\"entry-dgp-10112\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διηθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1594 na letra δ · nº geral 10112</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 filtrar; coar 2 purificar; limpar 3 intr. infiltrar-se.</p></section></article>\n<article id=\"entry-dgp-10113\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διήθησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1595 na letra δ · nº geral 10113</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filtragem. 〈διηθέω〉</p></section></article>\n<article id=\"entry-dgp-10114\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διῆκα</h1><div class=\"entry-meta\"><span>DGP · ordem 1596 na letra δ · nº geral 10114</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de διΐημι.</p></section></article>\n<article id=\"entry-dgp-10115\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διηκονέω, διήκονος</h1><div class=\"entry-meta\"><span>DGP · ordem 1597 na letra δ · nº geral 10115</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = διακονέω, διάκονος.</p></section></article>\n<article id=\"entry-dgp-10116\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διηκόσιοι</h1><div class=\"entry-meta\"><span>DGP · ordem 1598 na letra δ · nº geral 10116</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = διακόσιοι.</p></section></article>\n<article id=\"entry-dgp-10117\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διήκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1599 na letra δ · nº geral 10117</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 atravessar, ac. 2 chegar atravessando; espalhar-se através, ac., gen. ou διά e gen. 3 chegar de um lugar, ἐκ e gen., a outro, εἰς, ἐπί, πρός e ac. 4 estender-se até, μέχρι e gen. 〈διά, ἥκω〉</p></section></article>\n<article id=\"entry-dgp-10118\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διημερεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1600 na letra δ · nº geral 10118</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 passar o dia com alguém, μετά e gen.; em uma ocupação, dat. ou ἐν e dat.; em um dado estado, adj. ou part. predic. 2 durar o dia todo.</p></section></article>\n<article id=\"entry-dgp-10119\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διηνεκέως</h1><div class=\"entry-meta\"><span>DGP · ordem 1601 na letra δ · nº geral 10119</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = διηνεκῶς.</p></section></article>\n<article id=\"entry-dgp-10120\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διηνεκής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1602 na letra δ · nº geral 10120</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 contínuo; sem interrupção 2 prolongado: νὺξ δ. luc. noite longa 3 duradouro; perpétuo: νόμος δ. plat. lei perpétua; εἰς τὸ διενεκές n.t. para sempre 4 de uma só peça; sem emenda: ῥάβδος δ. hom. vara feita de uma só peça de lenho, i.e., vara sólida. 〈διά, ἐνεγκεῖν〉</p></section></article>\n<article id=\"entry-dgp-10121\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διήνεμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1603 na letra δ · nº geral 10121</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">exposto aos ventos; batido pelos ventos. 〈διά, ἄνεμος〉</p></section></article>\n<article id=\"entry-dgp-10122\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διῃρημένως</h1><div class=\"entry-meta\"><span>DGP · ordem 1604 na letra δ · nº geral 10122</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. separadamente. 〈διαιρέω〉</p></section></article>\n<article id=\"entry-dgp-10123\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διήρης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1605 na letra δ · nº geral 10123</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do nível superior de uma construção 2 duplo ♦ τὸ διῆρες 3 navio com duas fileiras de remadores; birreme.</p></section></article>\n<article id=\"entry-dgp-10124\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίηται</h1><div class=\"entry-meta\"><span>DGP · ordem 1606 na letra δ · nº geral 10124</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. δίω.</p></section></article>\n<article id=\"entry-dgp-10125\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διήφυσε</h1><div class=\"entry-meta\"><span>DGP · ordem 1607 na letra δ · nº geral 10125</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διαφύσσω.</p></section></article>\n<article id=\"entry-dgp-10126\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διηχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1608 na letra δ · nº geral 10126</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 deixar passar o som de, ac. 2 intr. retinir; ressoar. 〈διηχής〉</p></section></article>\n<article id=\"entry-dgp-10127\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διηχής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1609 na letra δ · nº geral 10127</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ressoa. 〈διά, ἦχος〉</p></section></article>\n<article id=\"entry-dgp-10128\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διθάλασσος,</h1><div class=\"entry-meta\"><span>DGP · ordem 1610 na letra δ · nº geral 10128</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. διθάλαττος, ος, ον tard. 1 banhado por dois mares 2 que se divide em dois mares. 〈δίς, θάλασσα〉</p></section></article>\n<article id=\"entry-dgp-10129\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίθηκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1611 na letra δ · nº geral 10129</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de dois gumes. 〈δίς, θήγω〉</p></section></article>\n<article id=\"entry-dgp-10130\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίθρονος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1612 na letra δ · nº geral 10130</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com trono duplo; com dois reis. 〈δίς, θρόνος〉</p></section></article>\n<article id=\"entry-dgp-10131\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διθυραμβικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1613 na letra δ · nº geral 10131</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que convém ao ditirambo; diti­râmbico ♦ τά διθυραμβικά 2 poemas ditirâmbicos. 〈διθύραμβος〉</p></section></article>\n<article id=\"entry-dgp-10132\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διθυραμβοποιός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1614 na letra δ · nº geral 10132</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">autor de ditirambos. 〈διθύ­ραμβος, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-10133\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διθύραμβος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1615 na letra δ · nº geral 10133</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ditirambo, poema em honra de Dioniso ou de outra divindade 2 composição de estilo ditirâmbico 3 Ditirambo, epít. de Dioniso.</p></section></article>\n<article id=\"entry-dgp-10134\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίθυρος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1616 na letra δ · nº geral 10134</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de duas portas 2 de dois envoltórios 3 de dois compartimentos 4 de dupla folha (escrito). 〈δίς, θύρα〉</p></section></article>\n<article id=\"entry-dgp-10135\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιΐ</h1><div class=\"entry-meta\"><span>DGP · ordem 1617 na letra δ · nº geral 10135</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. de Ζεύς.</p></section></article>\n<article id=\"entry-dgp-10136\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διϊδεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 1618 na letra δ · nº geral 10136</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de διοράω e de δίοιδα.</p></section></article>\n<article id=\"entry-dgp-10137\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διϊέναι</h1><div class=\"entry-meta\"><span>DGP · ordem 1619 na letra δ · nº geral 10137</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. de δίειμι2 e de διΐημι.</p></section></article>\n<article id=\"entry-dgp-10138\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διΐημι</h1><div class=\"entry-meta\"><span>DGP · ordem 1620 na letra δ · nº geral 10138</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. διῆκα) 1 fazer passar de lado a lado; permitir a passagem de algo, ac., através de, ac., gen. ou διά e gen.· δ. ξίφος λαιμῶν eur. fazer a lança trespassar a garganta 2 deixar passar; fazer partir: δ. στράτευμα xen. licenciar um exército ♦ méd. 3 dissolver; diluir. 〈διά, ἵημι〉</p></section></article>\n<article id=\"entry-dgp-10139\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διϊκνέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1621 na letra δ · nº geral 10139</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διΐξομαι, aor.2 διϊκόμεν) 1 ir de um extremo a outro de um relato; expor ponto por ponto; relatar 2 chegar atravessando; passar através de; penetrar, εἰς ou πρός e ac., μέχρι e gen. 3 (tempo) transcorrer. 〈διά, ἱκνέομαι〉</p></section></article>\n<article id=\"entry-dgp-10140\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ίϊος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1622 na letra δ · nº geral 10140</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Zeus. 〈∆ιός〉</p></section></article>\n<article id=\"entry-dgp-10141\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διϊπετής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1623 na letra δ · nº geral 10141</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 caído de Zeus; caído do céu: δ. πο­ταμός hom. rio formado de águas pluviais 2 que vem de Zeus; divino; celeste. 〈∆ιός, πίπτω〉</p></section></article>\n<article id=\"entry-dgp-10142\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διΐπτημι</h1><div class=\"entry-meta\"><span>DGP · ordem 1624 na letra δ · nº geral 10142</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 διέπτην; méd. pres. διίπταμαι, aor.2 διεπτάμην, 3ª sing. διέπτατο, inf. διαπτάσθαι) at. e méd. = διαπέτομαι.</p></section></article>\n<article id=\"entry-dgp-10143\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διϊστέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1625 na letra δ · nº geral 10143</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de δίοιδα.</p></section></article>\n<article id=\"entry-dgp-10144\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διΐστημι</h1><div class=\"entry-meta\"><span>DGP · ordem 1626 na letra δ · nº geral 10144</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. διίστην, fut. διαστήσω, aor. διέστησα, aor.2 intr. διήστην, perf. διέστηκα, m.-q.-perf. διειστήκειν) at. e méd. 1 dispor separadamente; organizar; distinguir 2 intr. fixar-se separadamente; separar-se; afastar-se 3 intr. dividir-se; desunir-se. 〈διά, ἵστημι〉</p></section></article>\n<article id=\"entry-dgp-10145\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διϊστορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1627 na letra δ · nº geral 10145</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. relatar.</p></section></article>\n<article id=\"entry-dgp-10146\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διϊσχυρίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1628 na letra δ · nº geral 10146</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. διϊσχυριζόμην) 1 afirmar veementemente algo, ac. ou or. inf. ou conj. (ὅτι, ὡς) 2 insistir muito em, dat. 〈διά, ἰσχυρίζω〉</p></section></article>\n<article id=\"entry-dgp-10147\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διίωμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1629 na letra δ · nº geral 10147</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1ª pl. pres. do subj. de δίειμι2.</p></section></article>\n<article id=\"entry-dgp-10148\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκα</h1><div class=\"entry-meta\"><span>DGP · ordem 1630 na letra δ · nº geral 10148</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = δίκη.</p></section></article>\n<article id=\"entry-dgp-10149\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαζέμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1631 na letra δ · nº geral 10149</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. poét. de δικάζω.</p></section></article>\n<article id=\"entry-dgp-10150\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1632 na letra δ · nº geral 10150</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐδίκαζον, fut. δικάσω, aor. ἐδίκασα, perf. δεδίκακα; pas. fut. δικασθήσομαι, aor. ἐδικάσθην, perf. δεδίκασμαι) 1 pronunciar sentença; ser juiz; fazer justiça: ἐγὼν αὐτὸς δικάσω hom. eu mesmo pronunciarei a sentença, ἀνὴρ κατὰ τὸ ὀρθὸν δικάζων her. homem que julga com retidão 2 julgar algo, ac. ou gen., ou alguém, dat.: δ. ἐγκλήματος xen. julgar um crime, δ. ἀλιτρά pínd. julgar os atos ímpios, δ. πρᾴως τοῖς ἀρχομένοις plat. julgar os subordinados com doçura, δ. τῷ ἀδικεῖσθαι φάσκοντι plat. fazer justiça a quem se diz lesado, Τρωσί τε καὶ ∆αναοῖσι δ. hom. decidir entre troianos e dânaos 3 sentenciar; decretar algo, ac.: δίκην ἄδικον ἐδίκασε her. pronunciou uma sentença iníqua, δ. φυγήν ésql. decretar o exílio 4 defender em juízo: δ. φόνον eur. defender-se de um crime de homicídio 5 decidir que, or. inf. ou conj. (ὡς): ἐδίκασαν αὐτονόμους εἶναι Λεπρεάτας her. decretaram que os Lepreatas fossem independentes, Τελμησσέων δικασάντων ὡς ἔσονται Σάρδιες ἀνάλωτοι her. tendo o oráculo de Telmessa pronunciado que Sardes não seria tomada ♦ méd. 6 intentar um processo; sustentar uma causa; mover uma ação contra alguém, dat. ou πρός e ac., a respeito de algo, gen. ou περί e gen., diante de um tribunal, πρός e ac.: πῶς ὀρθῶς ἂν ἐμοὶ δικάζοιτο; dem. com que direito moveria contra mim um processo? δ. πρὸς διαιτητήν att. citar diante de um árbitro, δ. τινὶ κακηγορίας lís. processar alguém por difamação.</p></section></article>\n<article id=\"entry-dgp-10151\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαιεῦν</h1><div class=\"entry-meta\"><span>DGP · ordem 1633 na letra δ · nº geral 10151</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. jôn. de δικαιόω.</p></section></article>\n<article id=\"entry-dgp-10152\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαϊκός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1634 na letra δ · nº geral 10152</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">levado à justiça. 〈δίκη〉</p></section></article>\n<article id=\"entry-dgp-10153\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαιοδοτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1635 na letra δ · nº geral 10153</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fazer justiça. 〈δίκαιος, δίδωμι〉</p></section></article>\n<article id=\"entry-dgp-10154\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαιοκρισία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1636 na letra δ · nº geral 10154</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. julgamento honesto. 〈δι­καιοκρίτης〉</p></section></article>\n<article id=\"entry-dgp-10155\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαιοκρίτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1637 na letra δ · nº geral 10155</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. juiz equânime. 〈δίκαιος, κρίτης〉</p></section></article>\n<article id=\"entry-dgp-10156\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαιολογέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1638 na letra δ · nº geral 10156</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(méd. fut. δικαιολογήσομαι) 1 pleitear: οἱ δικαιολογοῦντες luc. os advogados ♦ méd. 2 pleitear uma causa por uma questão, περί ou ὑπέρ e gen., diante de um magistrado, πρός e ac. 〈δίκαιος, λόγος〉</p></section></article>\n<article id=\"entry-dgp-10157\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαιολογία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1639 na letra δ · nº geral 10157</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 defesa; discurso 2 discurso do gênero judiciário. 〈δίκαιος, λόγος〉</p></section></article>\n<article id=\"entry-dgp-10158\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακαιοπραγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1640 na letra δ · nº geral 10158</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comportar-se com justiça, com retidão; praticar a justiça. 〈δίκαιος, πράττω〉</p></section></article>\n<article id=\"entry-dgp-10159\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαιοπράγημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1641 na letra δ · nº geral 10159</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação justa, reta. 〈δικαιο­πραγέω〉</p></section></article>\n<article id=\"entry-dgp-10160\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαιοπραγία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1642 na letra δ · nº geral 10160</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comportamento reto; justiça na ações. 〈δίκαιος, πράττω〉</p></section></article>\n<article id=\"entry-dgp-10161\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκαιος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 1643 na letra δ · nº geral 10161</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e α, ον 1 que se conforma às normas sociais, à lei; civilizado (pessoa): χαλεποί τε καὶ ἄγριοι οὐδὲ δίκαιοι hom. [homens] cruéis e selvagens e não civilizados 2 que cumpre os deveres em relação aos deuses e aos homens; justo; honesto; correto (pessoa): ἑαυτὸν παράσχων δίκαιον καὶ μέτριον ἐς τὰς πόλεις tuc. mostrando-se justo e moderado em relação às cidades, ὁ τὰ δίκαια ποιῶν δίκαιος plat. aquele que pratica a justiça é justo 3 conforme à lei; justo; legítimo; honesto: τὸ ἀνδραποδίζεσθαι τοὺς πολεμίους [δοκεῖ] δίκαιον xen. escravizar os inimigos parece conforme o direito 4 que se conforma a sua função; regrado; bom: δ. ἰητρός hipócr. bom médico, δ. συγγραφεύς luc. bom historiador 5 feito conforme a regra; regular; normal; bom: δίκαιον πηδάλιον pínd. leme bem ajustado, ἅρμα δίκαιον xen. carro bem equilibrado 6 exato; preciso (número): αἱ ἑκατὸν ὀργυιαὶ δίκαιαι her. cem braças exatas ♦ δίκαιος εἰμι, com inf. 7 tenho o direito de; é justo que eu: δίκαιός εἰμι κολάζειν ar. tenho o direito de punir 8 sou digno de; mereço: δίκαιός ἐστιν ἀπολωλέναι dem. ele merece perecer ♦ τὸ δίκαιον, τὰ δίκαια 9 o direito; a justiça: τὸ δίκαιον δοῦλος ἦν plat. segundo o direito; era escravo, μάχεσθαι ὑπὲρ τοῦ δικαίου plat. combater pela justiça, ἐκ τοῦ δικαίου por legítima inferência, τὰ δίκαια πράττεσθαί τινα ésql. infligir a alguém o tratamento merecido. 〈δίκη〉</p></section></article>\n<article id=\"entry-dgp-10162\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαιοσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1644 na letra δ · nº geral 10162</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 justiça; sentimento de justiça; pro­bidade; retidão 2 função de juiz 3 a Justiça, person. 〈δίκαιος〉</p></section></article>\n<article id=\"entry-dgp-10163\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαιότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1645 na letra δ · nº geral 10163</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">justiça. 〈δίκαιος〉</p></section></article>\n<article id=\"entry-dgp-10164\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1646 na letra δ · nº geral 10164</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. δικαιώσω e δικαιώσομαι, aor. ἐδικαίωσα, perf. desus.; pas. fut. δικαιωθήσομαι, aor. ἐδικαιώθην, perf. δεδικαίωμαι) 1 submeter à justiça; castigar; condenar, ac. 2 considerar justo; achar bom, conveniente, ac. ou inf. 3 desejar; querer, inf. 4 consentir em, inf. 5 tratar de modo justo; defender os direitos de; defender, ac. ♦ méd. 6 fazer justiça; condenar. 〈δίκαιος〉</p></section></article>\n<article id=\"entry-dgp-10165\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαίωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1647 na letra δ · nº geral 10165</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação justa; ato de justiça 2 correção de um erro; punição de uma falta 3 satisfação de um direito 4 decisão de justiça; julgamento; sentença 5 ordem; prescrição 6 decreto. 〈δικαιόω〉</p></section></article>\n<article id=\"entry-dgp-10166\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαίως</h1><div class=\"entry-meta\"><span>DGP · ordem 1648 na letra δ · nº geral 10166</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 conforme à justiça; com justiça; retamente 2 regularmente; normalmente; com razão 3 ver­dadeiramente; realmente.</p></section></article>\n<article id=\"entry-dgp-10167\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαίωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1649 na letra δ · nº geral 10167</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 submissão à justiça; confrontação com a regra; confrontação com a lei; justificação 2 reclamação de um direito 3 defesa; justificação 4 ação de tratar segundo a justiça; condenação; punição. 〈δικαιόω〉</p></section></article>\n<article id=\"entry-dgp-10168\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαιωτής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1650 na letra δ · nº geral 10168</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">δικαστής.</p></section></article>\n<article id=\"entry-dgp-10169\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικᾶν</h1><div class=\"entry-meta\"><span>DGP · ordem 1651 na letra δ · nº geral 10169</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. fut. jôn. de δικάζω.</p></section></article>\n<article id=\"entry-dgp-10170\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικανικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1652 na letra δ · nº geral 10170</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se ocupa da justiça; jurisconsulto 2 pejor. hábil em direito, em chicana 3 (coisas) referente ao tribunal; judiciário 4 litigioso; prolixo; fastidioso ♦ ἡ δικανική 5 a ciência do direito. 〈δίκη〉</p></section></article>\n<article id=\"entry-dgp-10171\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικάρδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1653 na letra δ · nº geral 10171</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem dois corações. 〈δίς, καρδία〉</p></section></article>\n<article id=\"entry-dgp-10172\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκασα</h1><div class=\"entry-meta\"><span>DGP · ordem 1654 na letra δ · nº geral 10172</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. poét. de δικάζω.</p></section></article>\n<article id=\"entry-dgp-10173\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικασπόλος, ος ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1655 na letra δ · nº geral 10173</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que faz justiça; justiceiro. 〈δίκη, πολέω〉</p></section></article>\n<article id=\"entry-dgp-10174\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκασσα</h1><div class=\"entry-meta\"><span>DGP · ordem 1656 na letra δ · nº geral 10174</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. poét. de δικάζω.</p></section></article>\n<article id=\"entry-dgp-10175\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαστήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1657 na letra δ · nº geral 10175</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">δικαστής.</p></section></article>\n<article id=\"entry-dgp-10176\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαστήριον, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1658 na letra δ · nº geral 10176</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lugar onde se julga; tribunal 2 conjunto dos que julgam; tribunal; corte. 〈δικάζω〉</p></section></article>\n<article id=\"entry-dgp-10177\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1659 na letra δ · nº geral 10177</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 juiz 2 justiceiro; vingador. 〈δικάζω〉</p></section></article>\n<article id=\"entry-dgp-10178\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1660 na letra δ · nº geral 10178</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem experiência da justiça 2 referente à justiça; judiciário ♦ ἡ δικαστική 3 profissão de juiz ♦ τὸ δικαστικόν 4 salário dos juízes. 〈δικάζω〉</p></section></article>\n<article id=\"entry-dgp-10179\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικαστικῶς à</h1><div class=\"entry-meta\"><span>DGP · ordem 1661 na letra δ · nº geral 10179</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">maneira dos juízes.</p></section></article>\n<article id=\"entry-dgp-10180\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικάστρια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1662 na letra δ · nº geral 10180</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">juíza.</p></section></article>\n<article id=\"entry-dgp-10181\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκελλα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1663 na letra δ · nº geral 10181</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">forcado de duas pontas.</p></section></article>\n<article id=\"entry-dgp-10182\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικελλίτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1664 na letra δ · nº geral 10182</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que trabalha com o forcado de duas pontas. 〈δίκελλα〉</p></section></article>\n<article id=\"entry-dgp-10183\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκεντρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1665 na letra δ · nº geral 10183</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com dois aguilhões. 〈δίς, κέντρον〉</p></section></article>\n<article id=\"entry-dgp-10184\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκερκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1666 na letra δ · nº geral 10184</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem duas caudas. 〈δίς, κέρκος〉</p></section></article>\n<article id=\"entry-dgp-10185\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1667 na letra δ · nº geral 10185</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 norma; uso; costume; maneira de ser ou de fazer: μνηστήρων οὐχ ἥδε δίκη τὸ πάροιθε hom. antes não era essa a maneira de agir dos pretendentes 2 regra a ser seguida; direito; justiça; eqüidade: μίσει πλέον ἢ δίκῃ κρίνειν tuc. decidir mais por ódio do que por justiça, δίκῃ, ἐν ou σὺν δίκῃ, μετὰ ou πρὸς δίκης, κατὰ δίκην com justiça, de maneira justa, ἄνευ δίκης, δίκης ἄτερ, πέρα δίκης, βίᾳ δίκης, δίχα δίκης sem justiça 3 direito; razão: δίκας τῶνδ᾽ ἐποπτεύσει ésql. examinará os direitos deles 4 punição; condenação; pena: δίκην δοῦναι sofrer punição, δίκην ἔχειν sofrer o castigo merecido, δ. τίνειν, ἐκτίνειν, ὑπέχειν sofrer a pena, o castigo, δίκην λαμβάνειν obter reparação, δίκην ἐπιτιθέναι infligir um castigo, δίκης τυγχάνειν dem. receber o que é justo, δίκην αἰτεῖν, ἔχειν obter satisfação 5 ação judiciária; processo privado (op. a γραφή ação pública): δίκη ἀσεβείας, κλοπῆς, φόνου processo por impiedade, roubo, assassínio, δίκαι ἐμπορικαί dem. litígios comerciais, δίκην ἄγειν ἐπὶ τοὺς δικαστάς plat. submeter uma questão aos juízes, δίκην διώκειν ser o demandante, δίκην φεύγειν ser o demandado, εἰς δίκην ou εἰς δίκας ἄγειν citar em justiça, γράφεσθαι δίκην plat. apresentar queixa; mover uma ação 6 julgamento; sentença; decisão: δίκαι ἰθεῖαι hes. julgamentos corretos, δίκην εἰπεῖν hom. pronunciar uma sentença, πρὸ δίκης antes do julgamento ♦ ἡ ∆ίκη 7 Dice; a Justiça person. 8 a Vingança ou o Castigo: ἡ κάτω ∆. sóf. a Dice infernal, i.e., as Erínias ♦ δίκην adv. 9 à maneira de, gen.: ὄρνιθος δίκην βλέπων ἄνω...βοσκημάτων δίκην κάτω ἀεὶ βλέποντες plat. olhando para o alto como os pássaros...olhando sempre para baixo como o gado.</p></section></article>\n<article id=\"entry-dgp-10186\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκην</h1><div class=\"entry-meta\"><span>DGP · ordem 1668 na letra δ · nº geral 10186</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. cf. δίκη.</p></section></article>\n<article id=\"entry-dgp-10187\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικηφόρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1669 na letra δ · nº geral 10187</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que traz a justiça; vingador. 〈δίκη, φέρω〉</p></section></article>\n<article id=\"entry-dgp-10188\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικλίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1670 na letra δ · nº geral 10188</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 com duas fechaduras; com duas barras; com dois ferrolhos ♦ ὁ, ἡ δικλίς 2 porta com duas fechaduras; porta com dois batentes. 〈δίς, κλείς〉</p></section></article>\n<article id=\"entry-dgp-10189\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικογραφία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1671 na letra δ · nº geral 10189</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">discurso redigido por outro. 〈δίκη, γράφω〉</p></section></article>\n<article id=\"entry-dgp-10190\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικοδίφης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1672 na letra δ · nº geral 10190</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amante de processos. 〈δίκη, διφάω〉</p></section></article>\n<article id=\"entry-dgp-10191\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικολογέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1673 na letra δ · nº geral 10191</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pronunciar discursos; advogar. 〈δικολόγος〉</p></section></article>\n<article id=\"entry-dgp-10192\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικολόγος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1674 na letra δ · nº geral 10192</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">advogado. 〈δίκη, λέγω〉</p></section></article>\n<article id=\"entry-dgp-10193\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικόρυμβος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1675 na letra δ · nº geral 10193</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com dois cumes. 〈δίς, κόρυμβος〉</p></section></article>\n<article id=\"entry-dgp-10194\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικόρυφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1676 na letra δ · nº geral 10194</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 com dois cumes; com o cume bipartido 2 com a cabeleira repartida em dois. 〈δίς, κορυφή〉</p></section></article>\n<article id=\"entry-dgp-10195\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκρανος, ος ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1677 na letra δ · nº geral 10195</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bifurcado ♦ τὸ δίκρανον 2 forcado. 〈δίς, κάρα〉</p></section></article>\n<article id=\"entry-dgp-10196\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικρατής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1678 na letra δ · nº geral 10196</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">duplamente poderoso. 〈δίς, κράτος〉</p></section></article>\n<article id=\"entry-dgp-10197\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκροτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1679 na letra δ · nº geral 10197</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que golpeia duas vezes (remos de duas pás) 2 que ressoa duplamente 3 que pulsa duas vezes (pulso) 4 de duas vias (estrada). 〈δίς, κρότος〉</p></section></article>\n<article id=\"entry-dgp-10198\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικτατορία</h1><div class=\"entry-meta\"><span>DGP · ordem 1680 na letra δ · nº geral 10198</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e δικτατορεία, ας = δικτατωρία.</p></section></article>\n<article id=\"entry-dgp-10199\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικτάτωρ, ορος</h1><div class=\"entry-meta\"><span>DGP · ordem 1681 na letra δ · nº geral 10199</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ωρος (ὁ) ditador.</p></section></article>\n<article id=\"entry-dgp-10200\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικτατωρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1682 na letra δ · nº geral 10200</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ditadura. 〈δικτάτωρ〉</p></section></article>\n";
